static bool
rtl8125_is_autoneg_mode_valid(u32 autoneg)
{
    switch(autoneg) {
        case AUTONEG_ENABLE:
        case AUTONEG_DISABLE:
            return true;
            
        default:
            return false;
    }
}

bool rtl8125_is_speed_mode_valid(u32 speed)
{
    switch(speed) {
        case SPEED_5000:
        case SPEED_2500:
        case SPEED_1000:
        case SPEED_100:
        case SPEED_10:
            return true;
            
        default:
            return false;
    }
}

static bool
rtl8125_is_duplex_mode_valid(u8 duplex)
{
    switch(duplex) {
        case DUPLEX_FULL:
        case DUPLEX_HALF:
                return true;
        default:
                return false;
    }
}

void rtl8125_set_link_option(struct rtl8125_private *tp,
                        u8 autoneg,
                        u32 speed,
                        u8 duplex,
                        enum rtl8125_fc_mode fc)
{
    u64 adv;

    if (!rtl8125_is_speed_mode_valid(speed))
        speed = SPEED_5000;

    if (!rtl8125_is_duplex_mode_valid(duplex))
        duplex = DUPLEX_FULL;

    if (!rtl8125_is_autoneg_mode_valid(autoneg))
        autoneg = AUTONEG_ENABLE;

    speed = min(speed, tp->HwSuppMaxPhyLinkSpeed);
    adv = 0;
    
    switch(speed) {
        case SPEED_5000:
                adv |= RTK_ADVERTISED_5000baseX_Full;
                /* fallthrough */
        case SPEED_2500:
            adv |= ADVERTISED_2500baseX_Full;
            /* fallthrough */
        default:
            adv |= (ADVERTISED_10baseT_Half | ADVERTISED_10baseT_Full |
                    ADVERTISED_100baseT_Half | ADVERTISED_100baseT_Full |
                    ADVERTISED_1000baseT_Half | ADVERTISED_1000baseT_Full);
            break;
    }
    tp->autoneg = autoneg;
    tp->speed = speed;
    tp->duplex = duplex;
    tp->advertising = adv;
    tp->fcpause = fc;
}

static inline u16 map_phy_ocp_addr(u16 PageNum, u8 RegNum)
{
    u16 OcpPageNum = 0;
    u8 OcpRegNum = 0;
    u16 OcpPhyAddress = 0;
    
    if ( PageNum == 0 ) {
        OcpPageNum = OCP_STD_PHY_BASE_PAGE + ( RegNum / 8 );
        OcpRegNum = 0x10 + ( RegNum % 8 );
    } else {
        OcpPageNum = PageNum;
        OcpRegNum = RegNum;
    }
    
    OcpPageNum <<= 4;
    
    if ( OcpRegNum < 16 ) {
        OcpPhyAddress = 0;
    } else {
        OcpRegNum -= 16;
        OcpRegNum <<= 1;
        
        OcpPhyAddress = OcpPageNum + OcpRegNum;
    }
    
    
    return OcpPhyAddress;
}

void mdio_real_direct_write_phy_ocp(struct rtl8125_private *tp,
                                           u16 RegAddr,
                                           u16 value)
{
    u32 data32;
    int i;
    
#if LINUX_VERSION_CODE >= KERNEL_VERSION(2,6,18)
    WARN_ON_ONCE(RegAddr % 2);
#endif
    data32 = RegAddr/2;
    data32 <<= OCPR_Addr_Reg_shift;
    data32 |= OCPR_Write | value;
    
    RTL_W32(tp, PHYOCP, data32);
    for (i = 0; i < 100; i++) {
        udelay(1);
        
        if (!(RTL_R32(tp, PHYOCP) & OCPR_Flag))
            break;
    }
}

void mdio_direct_write_phy_ocp(struct rtl8125_private *tp,
                                      u16 RegAddr,
                                      u16 value)
{
    if (tp->rtk_enable_diag) return;
    
    mdio_real_direct_write_phy_ocp(tp, RegAddr, value);
}

