static u16
rtl8125_get_hw_phy_mcu_code_ver(struct rtl8125_private *tp)
{
        u16 hw_ram_code_ver;

        mdio_direct_write_phy_ocp(tp, 0xA436, 0x801E);
        hw_ram_code_ver = mdio_direct_read_phy_ocp(tp, 0xA438);

        return hw_ram_code_ver;
}

int rtl8125_check_hw_phy_mcu_code_ver(struct rtl8125_private *tp)
{
    int result;
    
    tp->hw_ram_code_ver = rtl8125_get_hw_phy_mcu_code_ver(tp);

    if (tp->hw_ram_code_ver == tp->sw_ram_code_ver) {
        tp->HwHasWrRamCodeToMicroP = TRUE;
        result = 1;
    } else {
        tp->HwHasWrRamCodeToMicroP = FALSE;
        result = 0;
    }
    return result;
}

static void
rtl8125_write_hw_phy_mcu_code_ver(struct rtl8125_private *tp)
{
    switch (tp->mcfg) {
        case CFG_METHOD_2:
        case CFG_METHOD_3:
        case CFG_METHOD_4:
        case CFG_METHOD_5:
            mdio_direct_write_phy_ocp(tp, 0xA436, 0x801E);
            mdio_direct_write_phy_ocp(tp, 0xA438, tp->sw_ram_code_ver);
            tp->hw_ram_code_ver = tp->sw_ram_code_ver;
            break;
    }
}

static void
rtl8125_acquire_phy_mcu_patch_key_lock(struct rtl8125_private *tp)
{
    u16 PatchKey;
    
    switch (tp->mcfg) {
        case CFG_METHOD_2:
            PatchKey = 0x8600;
            break;
        case CFG_METHOD_3:
            PatchKey = 0x8601;
            break;
        case CFG_METHOD_4:
            PatchKey = 0x3700;
            break;
        case CFG_METHOD_5:
            PatchKey = 0x3701;
            break;
        default:
            return;
    }
    mdio_direct_write_phy_ocp(tp, 0xA436, 0x8024);
    mdio_direct_write_phy_ocp(tp, 0xA438, PatchKey);
    mdio_direct_write_phy_ocp(tp, 0xA436, 0xB82E);
    mdio_direct_write_phy_ocp(tp, 0xA438, 0x0001);
}

static void
rtl8125_release_phy_mcu_patch_key_lock(struct rtl8125_private *tp)
{
    switch (tp->mcfg) {
        case CFG_METHOD_2:
        case CFG_METHOD_3:
        case CFG_METHOD_4:
        case CFG_METHOD_5:
            mdio_direct_write_phy_ocp(tp, 0xA436, 0x0000);
            mdio_direct_write_phy_ocp(tp, 0xA438, 0x0000);
            ClearEthPhyOcpBit(tp, 0xB82E, BIT_0);
            mdio_direct_write_phy_ocp(tp, 0xA436, 0x8024);
            mdio_direct_write_phy_ocp(tp, 0xA438, 0x0000);
            break;
        default:
            break;
    }
}

static bool
rtl8125_wait_phy_mcu_patch_request_ready(struct rtl8125_private *tp)
{
    u16 gphy_val;
    u16 WaitCount;
    bool bSuccess = TRUE;
    
    WaitCount = 0;
    do {
        gphy_val = mdio_direct_read_phy_ocp(tp, 0xB800);
        gphy_val &= BIT_6;
        udelay(100);
        WaitCount++;
    } while(gphy_val != BIT_6 && WaitCount < 1000);
    
    if (gphy_val != BIT_6 && WaitCount == 1000) bSuccess = FALSE;
    
    if (!bSuccess)
        IOLog("rtl8125_wait_phy_mcu_patch_request_ready fail.\n");
    
    return bSuccess;
}

bool
rtl8125_set_phy_mcu_patch_request(struct rtl8125_private *tp)
{
    u16 gphy_val;
    u16 WaitCount;
    bool bSuccess = TRUE;

    rtl8125_set_eth_phy_ocp_bit(tp, 0xB820, BIT_4);

    WaitCount = 0;
    
    do {
        gphy_val = mdio_direct_read_phy_ocp(tp, 0xB800);
        udelay(100);
        WaitCount++;
    } while (!(gphy_val & BIT_6) && (WaitCount < 1000));

    if (!(gphy_val & BIT_6) && (WaitCount == 1000))
        bSuccess = FALSE;

    if (!bSuccess)
        IOLog("rtl8125_set_phy_mcu_patch_request fail.\n");

    return bSuccess;
}

bool
rtl8125_clear_phy_mcu_patch_request(struct rtl8125_private *tp)
{
    u16 gphy_val;
    u16 WaitCount;
    bool bSuccess = TRUE;

    rtl8125_clear_eth_phy_ocp_bit(tp, 0xB820, BIT_4);

    WaitCount = 0;
    do {
        gphy_val = mdio_direct_read_phy_ocp(tp, 0xB800);
        udelay(100);
        WaitCount++;
    } while ((gphy_val & BIT_6) && (WaitCount < 1000));

    if ((gphy_val & BIT_6) && (WaitCount == 1000))
        bSuccess = FALSE;

    if (!bSuccess)
        DebugLog("rtl8125_clear_phy_mcu_patch_request fail.\n");

    return bSuccess;
}

static void
rtl8125_set_phy_mcu_ram_code(struct net_device *dev, const u16 *ramcode, u16 codesize)
{
    struct rtl8125_private *tp = netdev_priv(dev);
    u16 i;
    u16 addr;
    u16 val;
    
    if (ramcode == NULL || codesize % 2) {
        goto out;
    }
    
    for (i = 0; i < codesize; i += 2) {
        addr = ramcode[i];
        val = ramcode[i + 1];
        if (addr == 0xFFFF && val == 0xFFFF) {
            break;
        }
        mdio_direct_write_phy_ocp(tp, addr, val);
    }
    
out:
    return;
}

