void rtl8125_set_hw_phy_before_init_phy_mcu(struct rtl8125_private *tp)
{
    u16 PhyRegValue;
    
    switch (tp->mcfg) {
        case CFG_METHOD_4:
            mdio_direct_write_phy_ocp(tp, 0xBF86, 0x9000);
            
            SetEthPhyOcpBit(tp, 0xC402, BIT_10);
            ClearEthPhyOcpBit(tp, 0xC402, BIT_10);
            
            PhyRegValue = mdio_direct_read_phy_ocp(tp, 0xBF86);
            PhyRegValue &= (BIT_1 | BIT_0);
            
            if (PhyRegValue != 0)
                DebugLog("PHY watch dog not clear, value = 0x%x \n", PhyRegValue);
            
            mdio_direct_write_phy_ocp(tp, 0xBD86, 0x1010);
            mdio_direct_write_phy_ocp(tp, 0xBD88, 0x1010);
            
            ClearAndSetEthPhyOcpBit(tp,
                                    0xBD4E,
                                    BIT_11 | BIT_10,
                                    BIT_11);
            ClearAndSetEthPhyOcpBit(tp,
                                    0xBF46,
                                    BIT_11 | BIT_10 | BIT_9 | BIT_8,
                                    BIT_10 | BIT_9 | BIT_8);
            break;
    }
}

void rtl8125_hw_phy_config(struct rtl8125_private *tp)
{
    if (tp->resume_not_chg_speed)
        return;

    tp->phy_reset_enable(tp);

#ifndef ENABLE_USE_FIRMWARE_FILE
    if (!tp->rtl_fw) {
        if (tp->mcfg < CFG_METHOD_31)
            rtl8125_set_hw_phy_before_init_phy_mcu(tp);
        
        rtl8125_init_hw_phy_mcu(tp);
    }
#endif

    switch (tp->mcfg) {
        case CFG_METHOD_2:
            rtl8125_hw_phy_config_8125a_1(tp);
            break;
            
        case CFG_METHOD_3:
        case CFG_METHOD_6:
            rtl8125_hw_phy_config_8125a_2(tp);
            break;
            
        case CFG_METHOD_4:
            rtl8125_hw_phy_config_8125b_1(tp);
            break;
            
        case CFG_METHOD_5:
        case CFG_METHOD_7:
            rtl8125_hw_phy_config_8125b_2(tp);
            break;
            
        case CFG_METHOD_8:
            rtl8125_hw_phy_config_8125bp_1(tp);
            break;
            
        case CFG_METHOD_9:
            rtl8125_hw_phy_config_8125bp_2(tp);
            break;
            
        case CFG_METHOD_10:
            rtl8125_hw_phy_config_8125d_1(tp);
            break;
            
        case CFG_METHOD_11:
        case CFG_METHOD_13:
            rtl8125_hw_phy_config_8125d_2(tp);
            break;
            
        case CFG_METHOD_12:
            rtl8125_hw_phy_config_8125cp_1(tp);
            break;
            
        case CFG_METHOD_31:
            rtl8126_hw_phy_config_8126a_1(tp);
            break;
            
        case CFG_METHOD_32:
            rtl8126_hw_phy_config_8126a_2(tp);
            break;
            
        case CFG_METHOD_33:
            rtl8126_hw_phy_config_8126a_3(tp);
            break;
    }

    //legacy force mode(Chap 22)
    rtl8125_clear_eth_phy_ocp_bit(tp, 0xA5B4, BIT_15);

    /*ocp phy power saving*/
    /*
    if (tp->aspm) {
    if (tp->mcfg == CFG_METHOD_2 || tp->mcfg == CFG_METHOD_3 ||
        tp->mcfg == CFG_METHOD_6)
            rtl8125_enable_ocp_phy_power_saving(tp);
    }
    */

    rtl8125_mdio_write(tp, 0x1F, 0x0000);

    if (HW_HAS_WRITE_PHY_MCU_RAM_CODE(tp)) {
        if (tp->eee.eee_enabled)
            rtl8125_enable_eee(tp);
        else
            rtl8125_disable_eee(tp);
    }
}

void rtl8125_get_bios_setting(struct rtl8125_private *tp)
{
    switch (tp->mcfg) {
        case CFG_METHOD_2:
        case CFG_METHOD_3:
        case CFG_METHOD_4:
        case CFG_METHOD_5:
            tp->bios_setting = RTL_R32(tp, TimeInt2);
            break;
    }
}

void rtl8125_set_bios_setting(struct rtl8125_private *tp)
{    
    switch (tp->mcfg) {
        case CFG_METHOD_2:
        case CFG_METHOD_3:
        case CFG_METHOD_4:
        case CFG_METHOD_5:
            RTL_W32(tp, TimeInt2, tp->bios_setting);
            break;
    }
}



/******************************************************************************
 * rtl8125_rar_set - Puts an ethernet address into a receive address register.
 *
 * tp - The private data structure for driver
 * addr - Address to put into receive address register
 *****************************************************************************/

void rtl8125_rar_set(struct rtl8125_private *tp, const u8 *addr)

{
    uint32_t rar_low = 0;
    uint32_t rar_high = 0;
    
    rar_low = ((uint32_t) addr[0] |
               ((uint32_t) addr[1] << 8) |
               ((uint32_t) addr[2] << 16) |
               ((uint32_t) addr[3] << 24));
    
    rar_high = ((uint32_t) addr[4] |
                ((uint32_t) addr[5] << 8));
    
    rtl8125_enable_cfg9346_write(tp);
    RTL_W32(tp, MAC0, rar_low);
    RTL_W32(tp, MAC4, rar_high);
    
    rtl8125_disable_cfg9346_write(tp);
}

static void rtl8125_phy_power_up(struct rtl8125_private *tp)
{
    if (rtl8125_is_in_phy_disable_mode(tp))
            return;

    rtl8125_mdio_write(tp, 0x1F, 0x0000);
    rtl8125_mdio_write(tp, MII_BMCR, BMCR_ANENABLE);

    //wait ups resume (phy state 3)
    rtl8125_wait_phy_ups_resume(tp, 3);
}

void rtl8125_phy_power_down(struct rtl8125_private *tp)
{
    rtl8125_mdio_write(tp, 0x1F, 0x0000);
    rtl8125_mdio_write(tp, MII_BMCR, BMCR_ANENABLE | BMCR_PDOWN);
}

u8 rtl8125_get_l1off_cap_bits(struct rtl8125_private *tp)
{
    u8 l1offCapBits = (BIT_0 | BIT_1);
    
    switch (tp->mcfg) {
        case CFG_METHOD_4:
        case CFG_METHOD_5:
        case CFG_METHOD_7:
        case CFG_METHOD_8:
        case CFG_METHOD_9:
        case CFG_METHOD_10:
        case CFG_METHOD_11:
        case CFG_METHOD_12:
        case CFG_METHOD_13:
        case CFG_METHOD_31:
        case CFG_METHOD_32:
        case CFG_METHOD_33:
            l1offCapBits |= (BIT_2 | BIT_3);
            break;
            
        default:
            break;
    }
    return l1offCapBits;
}

void rtl8125_set_l1_l0s_entry_latency(struct rtl8125_private *tp)
{
    u32 csi_tmp;
    u32 temp;

    temp = 0x27 & 0x3f;
    temp <<= 24;
    /*set PCI configuration space offset 0x70F to setting*/
    /*When the register offset of PCI configuration space larger than 0xff, use CSI to access it.*/

    csi_tmp = rtl8125_csi_read(tp, 0x70c) & 0xc0ffffff;
    rtl8125_csi_write(tp, 0x70c, csi_tmp | temp);
}

void rtl8125_set_rms(struct rtl8125_private *tp, u16 rms)
{
    switch (tp->mcfg) {
        case CFG_METHOD_8:
        case CFG_METHOD_9:
        case CFG_METHOD_10:
        case CFG_METHOD_11:
        case CFG_METHOD_12:
        case CFG_METHOD_13:
        case CFG_METHOD_31:
        case CFG_METHOD_32:
        case CFG_METHOD_33:
                rms |= AcceppVlanPhys;
                break;
            
        default:
                rms &= ~AcceppVlanPhys;
                break;
    }
    RTL_W16(tp, RxMaxSize, rms);
}

static bool rtl8125_is_allow_access_dash_ocp(struct rtl8125_private *tp)
{
    bool allow_access = false;
    u16 mac_ocp_data;

    if (!HW_DASH_SUPPORT_DASH(tp))
        goto exit;

    allow_access = true;
    
    switch (tp->mcfg) {
        case CFG_METHOD_2:
        case CFG_METHOD_3:
            mac_ocp_data = rtl8125_mac_ocp_read(tp, 0xd460);
            
            if (mac_ocp_data == 0xffff || !(mac_ocp_data & BIT_0))
                allow_access = false;
            break;
            
        case CFG_METHOD_8:
        case CFG_METHOD_9:
            mac_ocp_data = rtl8125_mac_ocp_read(tp, 0xd4c0);
            
            if (mac_ocp_data == 0xffff || (mac_ocp_data & BIT_3))
                allow_access = false;
            break;
            
        default:
            goto exit;
    }
exit:
    return allow_access;
}

static u32 rtl8125_get_dash_fw_ver(struct rtl8125_private *tp)
{
    u32 ver = 0xffffffff;

    if (FALSE == HW_DASH_SUPPORT_GET_FIRMWARE_VERSION(tp))
        goto exit;

    ver = rtl8125_ocp_read(tp, OCP_REG_FIRMWARE_MAJOR_VERSION, 4);

exit:
        return ver;
}

static int _rtl8125_check_dash(struct rtl8125_private *tp)
{
    if (!tp->AllowAccessDashOcp)
        return 0;

    if (!HW_DASH_SUPPORT_IPC2(tp))
        return 0;

    if (rtl8125_ocp_read(tp, 0x128, 1) & BIT_0)
        return 1;

    return 0;
}

static int rtl8125_check_dash(struct rtl8125_private *tp)
{
    if (HW_DASH_SUPPORT_DASH(tp) && _rtl8125_check_dash(tp)) {
        u32 ver = rtl8125_get_dash_fw_ver(tp);
        
        if (!(ver == 0 || ver == 0xffffffff))
            return 1;
    }
    return 0;
}

static bool
_rtl8125_backup_phy_fuse_dout_v4(struct rtl8125_private *tp)
{
    u16 i;

    for (i = 0; i < R8125_PHY_FUSE_DOUT_NUM; i++) {
        rtl8125_clear_and_set_eth_phy_ocp_bit(tp, 0xA460, 0x001F, i);
        tp->BackupPhyFuseDout[i] = mdio_direct_read_phy_ocp(tp, 0xA462);
    }
    if (tp->HwSuppEsdVer == 4) {
        tp->BackupPhyFuseDout[3] |= 0xF000;
        tp->BackupPhyFuseDout[7] |= 0x03FF;
        tp->BackupPhyFuseDout[4] = USHRT_MAX;
        tp->BackupPhyFuseDout[5] = USHRT_MAX;
        tp->BackupPhyFuseDout[6] = USHRT_MAX;
    } else if (tp->HwSuppEsdVer == 5) {
        tp->BackupPhyFuseDout[30] = USHRT_MAX;
        tp->BackupPhyFuseDout[31] = USHRT_MAX;
    }
    return TRUE;
}

static bool
rtl8125_backup_phy_fuse_dout(struct rtl8125_private *tp)
{
    if (tp->HwSuppEsdVer == 4 || tp->HwSuppEsdVer == 5)
        return _rtl8125_backup_phy_fuse_dout_v4(tp);
    else
        return FALSE;
}

void rtl8125_setup_mqs_reg(struct rtl8125_private *tp)
{
    switch (tp->HwSuppTxNoCloseVer) {
        case 4:
        case 5:
            tp->HwCloPtrReg = HW_CLO_PTR0_8126;
            tp->SwTailPtrReg = SW_TAIL_PTR0_8126;
            break;
            
        case 6:
            tp->HwCloPtrReg = HW_CLO_PTR0_8125BP;
            tp->SwTailPtrReg = SW_TAIL_PTR0_8125BP;
            break;
            
        default:
            tp->HwCloPtrReg = HW_CLO_PTR0_8125;
            tp->SwTailPtrReg = SW_TAIL_PTR0_8125;
            break;
    }
}

void rtl8125_init_software_variable(struct rtl8125_private *tp)
{
    u8 tmp;
    
    switch (tp->mcfg) {
        case CFG_METHOD_2:
        case CFG_METHOD_3:
            tmp = (u8)rtl8125_mac_ocp_read(tp, 0xD006);
            
            if (tmp == 0x02 || tmp == 0x04)
                    tp->HwSuppDashVer = 2;
            break;
            
        case CFG_METHOD_8:
        case CFG_METHOD_9:
                tp->HwSuppDashVer = 4;
                break;
            
        default:
                tp->HwSuppDashVer = 0;
                break;
    }

    switch (tp->mcfg) {
        case CFG_METHOD_2:
        case CFG_METHOD_3:
                if (HW_DASH_SUPPORT_DASH(tp))
                    tp->HwSuppOcpChannelVer = 2;
                break;
            
        case CFG_METHOD_8:
        case CFG_METHOD_9:
        case CFG_METHOD_12:
                tp->HwSuppOcpChannelVer = 2;
                break;
    }
    tp->AllowAccessDashOcp = rtl8125_is_allow_access_dash_ocp(tp);
    tp->HwPkgDet = rtl8125_mac_ocp_read(tp, 0xDC00);
    tp->HwPkgDet = (tp->HwPkgDet >> 3) & 0x07;

    //tp->HwSuppNowIsOobVer = 1;

    switch (tp->mcfg) {
        case CFG_METHOD_2:
        case CFG_METHOD_3:
        case CFG_METHOD_4:
        case CFG_METHOD_5:
        case CFG_METHOD_6:
        case CFG_METHOD_7:
            tp->HwPcieSNOffset = 0x16C;
            break;
            
        case CFG_METHOD_8:
        case CFG_METHOD_9:
        case CFG_METHOD_10:
        case CFG_METHOD_11:
        case CFG_METHOD_12:
        case CFG_METHOD_13:
            tp->HwPcieSNOffset = 0x168;
            break;
            
        case CFG_METHOD_31:
        case CFG_METHOD_32:
        case CFG_METHOD_33:
            tp->HwPcieSNOffset = 0x174;
            break;
    }
    tp->DASH = rtl8125_check_dash(tp);

    if (tp->DASH) {
        tp->eee.eee_enabled = 0;

        //tp->SizeOfSendToFwBuffer = SEND_TO_FW_BUF_SIZE;
        //tp->SizeOfRecvFromFwBuffer = RECV_FROM_FW_BUF_SIZE;

        tp->DashFirmwareVersion = rtl8125_get_dash_fw_ver(tp);
    }

    if (tp->aspm) {
        tp->org_pci_offset_99 = rtl8125_csi_fun0_read_byte(tp, 0x99);
        tp->org_pci_offset_99 &= ~(BIT_5|BIT_6);

        switch (tp->mcfg) {
            case CFG_METHOD_2:
            case CFG_METHOD_3:
            case CFG_METHOD_6:
                tp->org_pci_offset_180 = rtl8125_csi_fun0_read_byte(tp, 0x264);
                break;
                    
            case CFG_METHOD_4:
            case CFG_METHOD_5:
            case CFG_METHOD_7:
                tp->org_pci_offset_180 = rtl8125_csi_fun0_read_byte(tp, 0x214);
                break;
                    
            case CFG_METHOD_8:
            case CFG_METHOD_9:
            case CFG_METHOD_10:
            case CFG_METHOD_11:
            case CFG_METHOD_13:
                tp->org_pci_offset_180 = rtl8125_csi_fun0_read_byte(tp, 0x210);
                break;
                    
            case CFG_METHOD_12:
                tp->org_pci_offset_180 = rtl8125_csi_fun0_read_byte(tp, 0x184);
                break;
             
            case CFG_METHOD_31:
            case CFG_METHOD_32:
            case CFG_METHOD_33:
                tp->org_pci_offset_180 = rtl8125_csi_fun0_read_byte(tp, 0x22c);
                break;
        }
    }
    //tp->use_timer_interrupt = TRUE;

    switch (tp->mcfg) {
        case CFG_METHOD_2:
        case CFG_METHOD_3:
        case CFG_METHOD_4:
        case CFG_METHOD_5:
        case CFG_METHOD_8:
        case CFG_METHOD_9:
        case CFG_METHOD_10:
        case CFG_METHOD_11:
        case CFG_METHOD_12:
            tp->HwSuppMaxPhyLinkSpeed = 2500;
            break;
            
        case CFG_METHOD_31:
        case CFG_METHOD_32:
        case CFG_METHOD_33:
            tp->HwSuppMaxPhyLinkSpeed = 5000;
            break;
            
        default:
            tp->HwSuppMaxPhyLinkSpeed = 1000;
            break;
    }
/*
    if (timer_count == 0 || tp->mcfg == CFG_METHOD_DEFAULT)
            tp->use_timer_interrupt = FALSE;
*/
    //tp->ShortPacketSwChecksum = TRUE;
    //tp->UseSwPaddingShortPkt = TRUE;

    switch (tp->mcfg) {
        case CFG_METHOD_2:
        case CFG_METHOD_3:
        case CFG_METHOD_4:
        case CFG_METHOD_5:
        case CFG_METHOD_6:
        case CFG_METHOD_7:
        case CFG_METHOD_10:
        case CFG_METHOD_11:
        case CFG_METHOD_13:
        case CFG_METHOD_31:
        case CFG_METHOD_32:
        case CFG_METHOD_33:
            tp->HwSuppMagicPktVer = WAKEUP_MAGIC_PACKET_V3;
            break;
            
        default:
            tp->HwSuppMagicPktVer = WAKEUP_MAGIC_PACKET_NOT_SUPPORT;
            break;
    }

    switch (tp->mcfg) {
        case CFG_METHOD_5:
        case CFG_METHOD_7:
            tp->HwSuppEsdVer = 4;
            break;
            
        case CFG_METHOD_10:
            tp->HwSuppEsdVer = 5;
            break;
            
        default:
            tp->HwSuppEsdVer = 1;
            break;
    }

    if (rtl8125_backup_phy_fuse_dout(tp))
        tp->TestPhyOcpReg = TRUE;

#ifdef ENABLE_USE_FIRMWARE_FILE
        tp->TestPhyOcpReg = FALSE;
#endif
/*
    tp->HwSuppLinkChgWakeUpVer = 3;
*/
    switch (tp->mcfg) {
        case CFG_METHOD_3:
        case CFG_METHOD_4:
        case CFG_METHOD_5:
        case CFG_METHOD_6:
        case CFG_METHOD_7:
        case CFG_METHOD_8:
        case CFG_METHOD_9:
        case CFG_METHOD_31:
        case CFG_METHOD_32:
        case CFG_METHOD_33:
            tp->HwSuppD0SpeedUpVer = 1;
            break;
            
        case CFG_METHOD_10:
        case CFG_METHOD_11:
        case CFG_METHOD_12:
        case CFG_METHOD_13:
            tp->HwSuppD0SpeedUpVer = 2;
            break;
    }

    tp->HwSuppCheckPhyDisableModeVer = 3;

    switch (tp->mcfg) {
        case CFG_METHOD_2:
        case CFG_METHOD_3:
        case CFG_METHOD_4:
        case CFG_METHOD_5:
        case CFG_METHOD_6:
        case CFG_METHOD_7:
            tp->HwSuppTxNoCloseVer = 3;
            break;
            
        case CFG_METHOD_8:
        case CFG_METHOD_9:
        case CFG_METHOD_10:
        case CFG_METHOD_11:
        case CFG_METHOD_12:
        case CFG_METHOD_13:
                tp->HwSuppTxNoCloseVer = 6;
                break;
            
        case CFG_METHOD_31:
            tp->HwSuppTxNoCloseVer = 4;
            break;
            
        case CFG_METHOD_32:
        case CFG_METHOD_33:
            tp->HwSuppTxNoCloseVer = 5;
            break;
    }

    switch (tp->HwSuppTxNoCloseVer) {
        case 5:
        case 6:
            tp->MaxTxDescPtrMask = MAX_TX_NO_CLOSE_DESC_PTR_MASK_V4;
            break;
            
        case 4:
            tp->MaxTxDescPtrMask = MAX_TX_NO_CLOSE_DESC_PTR_MASK_V3;
            break;
            
        case 3:
            tp->MaxTxDescPtrMask = MAX_TX_NO_CLOSE_DESC_PTR_MASK_V2;
            break;
            
        default:
            DebugLog("Hw doesn't support TxNoClose!");
            break;
    }
    switch (tp->mcfg) {
        case CFG_METHOD_2:
        case CFG_METHOD_3:
        case CFG_METHOD_6:
            tp->RequireLSOPatch = TRUE;
            break;
    }

    switch (tp->mcfg) {
        case CFG_METHOD_2:
            tp->sw_ram_code_ver = NIC_RAMCODE_VERSION_CFG_METHOD_2;
            break;
            
        case CFG_METHOD_3:
        case CFG_METHOD_6:
            tp->sw_ram_code_ver = NIC_RAMCODE_VERSION_CFG_METHOD_3;
            break;
            
        case CFG_METHOD_4:
            tp->sw_ram_code_ver = NIC_RAMCODE_VERSION_CFG_METHOD_4;
            break;
            
        case CFG_METHOD_5:
        case CFG_METHOD_7:
            tp->sw_ram_code_ver = NIC_RAMCODE_VERSION_CFG_METHOD_5;
            break;
            
        case CFG_METHOD_8:
            tp->sw_ram_code_ver = NIC_RAMCODE_VERSION_CFG_METHOD_8;
            break;
            
        case CFG_METHOD_9:
            tp->sw_ram_code_ver = NIC_RAMCODE_VERSION_CFG_METHOD_9;
            break;
            
        case CFG_METHOD_10:
            tp->sw_ram_code_ver = NIC_RAMCODE_VERSION_CFG_METHOD_10;
            break;
            
        case CFG_METHOD_11:
        case CFG_METHOD_13:
            tp->sw_ram_code_ver = NIC_RAMCODE_VERSION_CFG_METHOD_11;
            break;
            
        case CFG_METHOD_12:
            tp->sw_ram_code_ver = NIC_RAMCODE_VERSION_CFG_METHOD_12;
            break;
            
        case CFG_METHOD_31:
            tp->sw_ram_code_ver = NIC_RAMCODE_VERSION_CFG_METHOD_31;
            break;
            
        case CFG_METHOD_32:
            tp->sw_ram_code_ver = NIC_RAMCODE_VERSION_CFG_METHOD_32;
            break;
            
        case CFG_METHOD_33:
            tp->sw_ram_code_ver = NIC_RAMCODE_VERSION_CFG_METHOD_33;
            break;
    }
    if (tp->HwIcVerUnknown) {
        tp->NotWrRamCodeToMicroP = TRUE;
        tp->NotWrMcuPatchCode = TRUE;
    }
    rtl8125_check_hw_phy_mcu_code_ver(tp);

    switch (tp->mcfg) {
        case CFG_METHOD_3:
        case CFG_METHOD_6:
            if ((rtl8125_mac_ocp_read(tp, 0xD442) & BIT_5) &&
                (mdio_direct_read_phy_ocp(tp, 0xD068) & BIT_1))
                    tp->RequirePhyMdiSwapPatch = TRUE;
            break;
    }

    tp->HwSuppMacMcuVer = 2;

    tp->MacMcuPageSize = RTL8125_MAC_MCU_PAGE_SIZE;
/*
    switch (tp->mcfg) {
        case CFG_METHOD_4:
        case CFG_METHOD_5:
        case CFG_METHOD_7:
        case CFG_METHOD_8:
        case CFG_METHOD_9:
        case CFG_METHOD_10:
        case CFG_METHOD_11:
        case CFG_METHOD_12:
        case CFG_METHOD_13:
            tp->HwSuppNumTxQueues = 2;
            tp->HwSuppNumRxQueues = 4;
            break;
            
        default:
            tp->HwSuppNumTxQueues = 1;
            tp->HwSuppNumRxQueues = 1;
            break;
    }

    switch (tp->mcfg) {
        case CFG_METHOD_4:
        case CFG_METHOD_5:
        case CFG_METHOD_7:*/
            /* mac ptp *//*
            tp->HwSuppPtpVer = 1;
            break;
            
        case CFG_METHOD_10:
        case CFG_METHOD_11:
        case CFG_METHOD_12:
        case CFG_METHOD_13:*/
            /* phy ptp *//*
            tp->HwSuppPtpVer = 3;
            break;
    }
    //init interrupt
    switch (tp->mcfg) {
        case CFG_METHOD_4:
        case CFG_METHOD_5:
        case CFG_METHOD_7:
            tp->HwSuppIsrVer = 2;
            break;
            
        case CFG_METHOD_8:
        case CFG_METHOD_9:
            tp->HwSuppIsrVer = 4;
            break;
            
        case CFG_METHOD_10:
        case CFG_METHOD_11:
        case CFG_METHOD_13:
            tp->HwSuppIsrVer = 5;
            break;
            
        case CFG_METHOD_12:
            tp->HwSuppIsrVer = 7;
            break;
            
        default:
            tp->HwSuppIsrVer = 1;
            break;
    }

    tp->HwCurrIsrVer = tp->HwSuppIsrVer;

    if (tp->HwCurrIsrVer < 2 ||
        (tp->HwCurrIsrVer == 2 && tp->irq_nvecs < 19))
            tp->num_tx_rings = 1;

    //RSS
    switch (tp->mcfg) {
        case CFG_METHOD_4:
        case CFG_METHOD_5:
        case CFG_METHOD_7:
        case CFG_METHOD_8:
        case CFG_METHOD_9:
        case CFG_METHOD_10:
        case CFG_METHOD_11:
        case CFG_METHOD_12:
        case CFG_METHOD_13:
            tp->HwSuppRssVer = 5;
            tp->HwSuppIndirTblEntries = 128;
            break;
    }

        //interrupt mask
        rtl8125_setup_interrupt_mask(tp);
*/
    rtl8125_setup_mqs_reg(tp);


    switch (tp->mcfg) {
        case CFG_METHOD_2:
        case CFG_METHOD_3:
        case CFG_METHOD_6:
            tp->HwSuppIntMitiVer = 3;
            break;
            
        case CFG_METHOD_4:
        case CFG_METHOD_5:
        case CFG_METHOD_7:
        case CFG_METHOD_31:
            tp->HwSuppIntMitiVer = 4;
            break;
            
        case CFG_METHOD_32:
        case CFG_METHOD_33:
            tp->HwSuppIntMitiVer = 5;
            break;

        case CFG_METHOD_8:
        case CFG_METHOD_9:
        case CFG_METHOD_10:
        case CFG_METHOD_11:
        case CFG_METHOD_12:
        case CFG_METHOD_13:
            tp->HwSuppIntMitiVer = 6;
            break;
    }

    switch (tp->mcfg) {
        case CFG_METHOD_31:
        case CFG_METHOD_32:
        case CFG_METHOD_33:
            tp->HwSuppTcamVer = 2;
            tp->TcamNotValidReg = TCAM_NOTVALID_ADDR_V2;
            tp->TcamValidReg = TCAM_VALID_ADDR_V2;
            tp->TcamMaAddrcOffset = TCAM_MAC_ADDR_V2;
            tp->TcamVlanTagOffset = TCAM_VLAN_TAG_V2;
            break;
            
        default:
            tp->HwSuppTcamVer = 1;
            tp->TcamNotValidReg = TCAM_NOTVALID_ADDR;
            tp->TcamValidReg = TCAM_VALID_ADDR;
            tp->TcamMaAddrcOffset = TCAM_MAC_ADDR;
            tp->TcamVlanTagOffset = TCAM_VLAN_TAG;
            break;
    }

    //tp->HwSuppExtendTallyCounterVer = 1;

    switch (tp->mcfg) {
            case CFG_METHOD_10:
            case CFG_METHOD_11:
            case CFG_METHOD_13:
            tp->RequiredPfmPatch = TRUE;
            break;
    }

    switch (tp->mcfg) {
        case CFG_METHOD_2:
        case CFG_METHOD_3:
        case CFG_METHOD_4:
        case CFG_METHOD_5:
        case CFG_METHOD_6:
        case CFG_METHOD_7:
        case CFG_METHOD_31:
            tp->HwSuppRxDescType = RX_DESC_RING_TYPE_3;
            break;
            
        case CFG_METHOD_8:
        case CFG_METHOD_9:
        case CFG_METHOD_10:
        case CFG_METHOD_11:
        case CFG_METHOD_12:
        case CFG_METHOD_13:
        case CFG_METHOD_32:
        case CFG_METHOD_33:
            tp->HwSuppRxDescType = RX_DESC_RING_TYPE_4;
            break;
            
        default:
            tp->HwSuppRxDescType = RX_DESC_RING_TYPE_1;
            break;
    }
    //rtl8125_backup_led_select(tp);
    
    /* RTL8126 only */
    //tp->NicCustLedValue = RTL_R16(tp, CustomLED);

    tp->wol_opts = rtl8125_get_hw_wol(tp);
    tp->wol_enabled = (tp->wol_opts) ? WOL_ENABLED : WOL_DISABLED;

    rtl8125_set_link_option(tp, AUTONEG_ENABLE, SPEED_2500, DUPLEX_FULL,
                            rtl8125_fc_none);

    if (tp->mcfg != CFG_METHOD_DEFAULT) {
        struct ethtool_keee *eee = &tp->eee;

        eee->eee_enabled = 1;
        linkmode_set_bit(ETHTOOL_LINK_MODE_100baseT_Full_BIT, &eee->supported);
        linkmode_set_bit(ETHTOOL_LINK_MODE_1000baseT_Full_BIT, &eee->supported);
        linkmode_set_bit(ETHTOOL_LINK_MODE_100baseT_Full_BIT, &eee->advertised);
        linkmode_set_bit(ETHTOOL_LINK_MODE_1000baseT_Full_BIT, &eee->advertised);

        if (tp->mcfg > CFG_METHOD_3) {
            if (HW_SUPP_PHY_LINK_SPEED_2500M(tp)) {
                linkmode_set_bit(ETHTOOL_LINK_MODE_2500baseT_Full_BIT, &eee->supported);
                linkmode_set_bit(ETHTOOL_LINK_MODE_2500baseT_Full_BIT, &eee->advertised);
                linkmode_set_bit(ETHTOOL_LINK_MODE_5000baseT_Full_BIT, &eee->advertised);
            }
            if (HW_SUPP_PHY_LINK_SPEED_5000M(tp))
                linkmode_set_bit(ETHTOOL_LINK_MODE_5000baseT_Full_BIT, &eee->supported);
        }
        eee->tx_lpi_enabled = 1;
        eee->tx_lpi_timer = ETH_DATA_LEN + ETH_HLEN + 0x20;
    }
}
